 import { MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  vec4,
  color,
  mix,
  smoothstep,
  sin,
  fract,
  dot,
  length,
  texture,
  uniform,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, DoubleSide } = ctx.THREE;
  const group = new Group();
  group.name = config.id ?? 'hub-collection-card-1';

  const palette = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const { ink, paper, accent, surface } = palette;

  const tier = ctx.tier ?? 'T1';
  const grainStrength = tier === 'T0' ? 0.02 : 0.045;

  const timelines = [];

  // --- Backdrop stage -------------------------------------------------------
  const backGeo = new PlaneGeometry(7, 6);
  const stageOpacity = uniform(0.0);
  const backMat = new MeshBasicNodeMaterial({
    side: DoubleSide,
    transparent: true,
  });

  const u = uv();
  const grad = mix(
    color(new Color(ink)),
    color(new Color(surface)),
    smoothstep(0, 1, u.y)
  );
  const stageNoise = fract(sin(dot(u, vec2(12.9898, 78.233))).mul(43758.5453));
  const stageColorNode = mix(grad, stageNoise.xxx, 0.04);

  backMat.colorNode = stageColorNode;
  backMat.opacityNode = stageOpacity;

  const back = new Mesh(backGeo, backMat);
  back.position.z = -2.5;
  group.add(back);

  // --- Card image plane -----------------------------------------------------
  const srcRect = { x: 0, y: 0, w: 512, h: 320 };
  const srcAspect = srcRect.w / srcRect.h;
  const cardH = 1.6;
  const cardW = cardH * srcAspect;

  const cardGeo = new PlaneGeometry(1, 1);
  const cardMat = new MeshBasicNodeMaterial({
    side: DoubleSide,
    transparent: true,
  });

  const placeholder = mix(
    color(new Color(ink)),
    color(new Color(surface)),
    0.5
  );
  cardMat.colorNode = placeholder;

  const card = new Mesh(cardGeo, cardMat);
  card.scale.set(cardW, cardH, 1);
  group.add(card);

  // --- Accent / paper frame details ----------------------------------------
  const accentBarGeo = new PlaneGeometry(0.6, 0.04);
  const accentBarMat = new MeshBasicNodeMaterial({ side: DoubleSide });
  accentBarMat.colorNode = color(new Color(accent));
  const accentBar = new Mesh(accentBarGeo, accentBarMat);
  accentBar.position.set(0, -0.48, 0.01);
  card.add(accentBar);

  const paperLineGeo = new PlaneGeometry(1.08, 0.018);
  const paperLineMat = new MeshBasicNodeMaterial({
    side: DoubleSide,
    transparent: true,
    opacity: 0.25,
  });
  paperLineMat.colorNode = color(new Color(paper));
  const paperLine = new Mesh(paperLineGeo, paperLineMat);
  paperLine.position.set(0, 0.52, 0.01);
  card.add(paperLine);

  // --- Contact shadow -------------------------------------------------------
  const shadowGeo = new PlaneGeometry(1, 1);
  const shadowMat = new MeshBasicNodeMaterial({
    side: DoubleSide,
    transparent: true,
  });

  const shadowUv = uv().sub(vec2(0.5));
  const shadowDist = length(shadowUv);
  const shadowAlpha = smoothstep(0.5, 0.0, shadowDist).mul(0.5);
  shadowMat.colorNode = vec3(0, 0, 0);
  shadowMat.opacityNode = shadowAlpha;

  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -cardH * 0.5 - 0.15, 0.02);
  shadow.scale.set(cardW * 1.2, cardH * 0.6, 1);
  group.add(shadow);

  // --- Image texture --------------------------------------------------------
  const imageUrl = config.imageUrl;
  if (imageUrl) {
    ctx.textureLoader
      .loadTexture(imageUrl)
      .then((tex) => {
        if (!tex) return;

        tex.colorSpace = ctx.THREE.SRGBColorSpace;

        const imgW = tex.image?.width || srcRect.w;
        const imgH = tex.image?.height || srcRect.h;
        const su = srcRect.x / imgW;
        const sv = srcRect.y / imgH;
        const sw = srcRect.w / imgW;
        const sh = srcRect.h / imgH;

        const tileUv = uv()
          .mul(vec2(sw, sh))
          .add(vec2(su, sv));

        const sample = texture(tex, tileUv);
        const cardGrain = fract(
          sin(dot(uv().mul(vec2(1024, 1024)), vec2(12.9898, 78.233)))
            .mul(43758.5453)
        ).xxx;

        const graded = mix(sample.rgb, cardGrain, grainStrength);
        cardMat.colorNode = vec4(graded, sample.a);
        cardMat.needsUpdate = true;
      })
      .catch(() => {});
  }

  // --- Entrance motion ------------------------------------------------------
  card.position.y = 0.1;
  card.scale.set(cardW * 0.96, cardH * 0.96, 1);

  const intro = gsap.timeline();
  intro.to(
    card.position,
    { y: 0, duration: 0.75, ease: 'power3.out' },
    0
  );
  intro.to(
    card.scale,
    { x: cardW, y: cardH, z: 1, duration: 0.8, ease: 'power4.out' },
    0
  );
  intro.to(
    stageOpacity,
    { value: 1.0, duration: 0.55, ease: 'power2.out' },
    0
  );

  timelines.push(intro);

  // --- Contract -------------------------------------------------------------
  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timelines.forEach((tl) => {
      if (tl) tl.kill();
    });

    gsap.killTweensOf(card.position);
    gsap.killTweensOf(card.scale);
    gsap.killTweensOf(stageOpacity);

    cardGeo.dispose?.();
    cardMat.dispose?.();
    accentBarGeo.dispose?.();
    accentBarMat.dispose?.();
    paperLineGeo.dispose?.();
    paperLineMat.dispose?.();
    shadowGeo.dispose?.();
    shadowMat.dispose?.();
    backGeo.dispose?.();
    backMat.dispose?.();
  };

  return group;
}
